-- Converted: CREATE ROLE reader -> CREATE ROLE READER (Snowflake account-level role; unquoted name, resolves to READER)
-- Reason: Snowflake supports CREATE ROLE directly; plain CREATE ROLE keeps the Teradata behaviour of failing if the role already exists, and no privileges or role hierarchy are added because the source defines none
CREATE ROLE READER;

-- Converted: CREATE ROLE operator -> CREATE ROLE OPERATOR (Snowflake account-level role; unquoted name, resolves to OPERATOR)
-- Reason: Snowflake supports CREATE ROLE directly; plain CREATE ROLE keeps the Teradata behaviour of failing if the role already exists, and no privileges or role hierarchy are added because the source defines none
