-- Converted: CREATE SET TABLE sales.employee -> CREATE TABLE SALES.EMPLOYEE (naming map); removed SET and PRIMARY INDEX (employee_id); INTEGER kept as Snowflake INTEGER (NUMBER(38,0))
-- Reason: Snowflake has no SET/MULTISET table kinds or primary index; micro-partitioning replaces AMP hash distribution, and NUMBER(38,0) holds every Teradata INTEGER value without precision loss
CREATE TABLE SALES.EMPLOYEE (
  employee_id INTEGER,
  branch_id INTEGER
);

